#include <stdio.h>
#include <stdlib.h>

typedef struct { long long u, v; } Pt;

static Pt pts[100005];
static long long vals[100005];
static int bit[100005];
static int m;

static int cmpPt(const void *x, const void *y) {
    const Pt *p = (const Pt *)x, *q = (const Pt *)y;
    if (p->u != q->u) return (p->u > q->u) ? -1 : 1; /* u descendente */
    if (p->v != q->v) return (p->v < q->v) ? -1 : 1; /* v ascendente */
    return 0;
}

static int cmpLL(const void *x, const void *y) {
    long long a = *(const long long *)x, b = *(const long long *)y;
    return (a > b) - (a < b);
}

static void upd(int i) { for (; i <= m; i += i & (-i)) bit[i]++; }

static int qry(int i) {
    int s = 0;
    for (; i > 0; i -= i & (-i)) s += bit[i];
    return s;
}

int main(void) {
    int n;
    long long X1, X2;
    if (scanf("%d %lld %lld", &n, &X1, &X2) != 3) return 0;

    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        pts[i].u = X1 * a + b; /* y da reta em x = X1 */
        pts[i].v = X2 * a + b; /* y da reta em x = X2 */
        vals[i] = pts[i].v;
    }

    /* comprimir valores de v */
    qsort(vals, (size_t)n, sizeof(long long), cmpLL);
    m = 0;
    for (int i = 0; i < n; i++)
        if (m == 0 || vals[i] != vals[m - 1]) vals[m++] = vals[i];

    /* ordena por u descendente, desempate v ascendente */
    qsort(pts, (size_t)n, sizeof(Pt), cmpPt);

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        int lo = 0, hi = m - 1;
        long long target = pts[i].v;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (vals[mid] < target) lo = mid + 1; else hi = mid;
        }
        int r = lo + 1;
        ans += qry(r);
        upd(r);
    }

    printf("%lld\n", ans);
    return 0;
}
